mapper.select:
select
	t.TYPE_8 as type8 /* 投管资产大类 */
from FIN_PRODUCT_TYPE t
where t.FINPROD_ID = #{finprodId}
  and t.BRANCH = #{branch}

select
	t.TYPE_6 as type6 /* 投管资产二级类型 */
from FIN_PRODUCT_TYPE t
where t.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and t.BRANCH = #{branch,jdbcType=VARCHAR}

select t.sec_acct_id as secAcctId
from STL_SEC_ACCT_INFO t
where t.trd_acct_id = #{acctNo,jdbcType=VARCHAR}

SELECT v.SEC_ACCT_ID AS secAcctId
FROM PTL_CAPACCT_INFO t
		 LEFT JOIN STL_SEC_ACCT_INFO v ON t.ACCT_NO = v.TRD_ACCT_ID
		 LEFT JOIN STL_CAPACCT_INFO R ON T.ACCT_NO = R.ACCT_NO
	AND T.CCY = R.CCY
		 LEFT JOIN PTL_SEC_ACCT PSA
				   ON v.SEC_ACCT_ID = PSA.ACCT_NO
WHERE t.PORTFOLIO_ID = #{portfolioId}
  AND v.TRADE_PLACE = #{tradeMarket}
  AND t.ACCT_NO = #{acctNo}
  AND PSA.PORTFOLIO_ID = #{portfolioId}
  AND ROWNUM = 1
ORDER BY t.ACCT_NO

select eea.target_type as targetType /*目标类型*/
from ETR_ENTRUST_ADD eea
where eea.ENTRUST_ID = #{entrustId}

select
	NVL(FSCR.SCALE, 0)
from FIN_STDSEC_CONVERSE_RADIO FSCR
where FSCR.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
  AND FSCR.BRANCH = '0'
  AND FSCR.VDATE  <= #{vdate, jdbcType=DATE}
  AND NOT EXISTS (SELECT 1
				  FROM FIN_STDSEC_CONVERSE_RADIO FSCRINNER
				  WHERE FSCRINNER.FINPROD_ID = FSCR.FINPROD_ID
					AND FSCRINNER.BRANCH ='0'
					AND FSCRINNER.VDATE <= #{vdate, jdbcType=DATE}
					AND FSCRINNER.VDATE > FSCR.VDATE
	)

select tptd.unit_cprice as unitCprice, tptd.share_amt as shareAmt
from TRD_PRODUCT_TEMP_DEAL tptd
		 inner join TRD_PRODUCT_TEMP_DEAL_ADD tptda
					on tptd.trade_id = tptda.trade_id
where tptda.portfolio_id = #{portfolioId}
  and tptd.finprod_id = #{finprodId}
  and tptd.ps = #{ps}
  and tptd.trade_date = #{tradeDate,jdbcType=DATE}
order by tptd.create_time

select fpa.contract_multiplier
from FIN_PRODUCT_ADD fpa
where fpa.finprod_id = #{finprodId}

select

from fin_deal_pledge t1
where t1.finprod_id = #{vTradeId}
and t1.branch = #{branch}

